sys_transform_entry.source_script:
answer = (/*function transformEntry(source) { return new global.ExternalUserRegistrationUtil().getUserId(source); }*/
	function transformEntry(source) {
		var tfName = source.first_name.trim();
		var tlName = source.last_name.trim();
		var lowerID = tfName.toLowerCase() + "." + tlName.toLowerCase();
		var limitID = lowerID.length >= 40 ? lowerID.substring(0, 40) : limitID = lowerID;
		return getNextUserName(limitID);
	}
)(source);

function getNextUserName(limitID) {
	var gr = new GlideRecord('sys_user');
	gr.addEncodedQuery('user_nameSTARTSWITH' + limitID);
	gr.orderByDesc('user_name');
	gr.setLimit(1);
	gr.query();

	if (gr.next()) {
		var intName = gr.user_name + "";
		var getNum = intName.match(/(\d+)$/);
		var lastNum = getNum ? parseInt(getNum[1]) : 0;
		var nextNum = lastNum + 1;

		var newLen = (limitID + nextNum.toString()).length;
		if (newLen > 40) {
			getNextUserName(limitID.substring(0, 40 - nextNum.toString().length));
		} else {
			return limitID + nextNum.toString();
		}
	} else {
		return limitID;
	}
}
